

from __future__ import annotations

import os
from dataclasses import dataclass, asdict
from typing import Dict, List, Tuple

import numpy as np
import torch
import torch.nn as nn

from main_train_qmappo import AGENT_NAMES, AGENT_OBS_IDXS


@dataclass
class QMetaInitConfig:
    feature_dim: int = 11
    hidden_dim: int = 64
    init_dim: int = 6
    seed: int = 42


# The six output values generated by the Q-MAML-inspired Learner.
INIT_KEYS = [
    "theta_scale",      # initial std for PQC rotation parameters
    "input_scale",      # initial value for PQC input scaling
    "output_scale",     # initial value for actor output scale
    "log_std",          # initial Gaussian policy log std
    "final_bias",       # initial final action-head bias
    "ent_strength",     # initial entanglement mixing strength
]


class QMetaInitializer(nn.Module):
    """Small Learner network for Q-MAML-inspired initialization.

    Input:  agent/task complexity vector chi_i.
    Output: initial quantum actor configuration vector.
    """

    def __init__(self, cfg: QMetaInitConfig):
        super().__init__()
        self.cfg = cfg
        self.net = nn.Sequential(
            nn.Linear(cfg.feature_dim, cfg.hidden_dim),
            nn.Tanh(),
            nn.Linear(cfg.hidden_dim, cfg.hidden_dim),
            nn.Tanh(),
            nn.Linear(cfg.hidden_dim, cfg.init_dim),
        )

    def forward(self, x: torch.Tensor) -> torch.Tensor:
        raw = self.net(x)
        # Map raw outputs to stable initialization ranges.
        theta_scale = 0.015 + 0.075 * torch.sigmoid(raw[..., 0:1])
        input_scale = 0.45 + 0.40 * torch.sigmoid(raw[..., 1:2])
        output_scale = 0.38 + 0.32 * torch.sigmoid(raw[..., 2:3])
        log_std = -1.25 + 0.65 * torch.sigmoid(raw[..., 3:4])
        final_bias = 0.65 * torch.tanh(raw[..., 4:5])
        ent_strength = 0.03 + 0.17 * torch.sigmoid(raw[..., 5:6])
        return torch.cat([theta_scale, input_scale, output_scale, log_std, final_bias, ent_strength], dim=-1)


def _safe_corr_abs(x: np.ndarray, y: np.ndarray) -> float:
    x = np.asarray(x, dtype=np.float64)
    y = np.asarray(y, dtype=np.float64)
    if x.std() < 1e-8 or y.std() < 1e-8:
        return 0.0
    return float(abs(np.corrcoef(x, y)[0, 1]))


def compute_action_sensitivity_from_data(data_path: str = "world_model_data/wm_transitions.npz") -> Dict[str, float]:
    """Estimate each agent's dynamic influence from collected transition data.

    This is a lightweight proxy for task complexity. It measures how strongly each
    action dimension correlates with changes in the key SOC/inventory states.
    If the dataset is unavailable, it returns a manually defined fallback.
    """
    fallback = {
        "Battery": 0.45,
        "P2A": 1.00,
        "CHP": 0.70,
        "GB": 0.60,
        "EB": 0.55,
    }
    if not os.path.exists(data_path):
        return fallback

    try:
        data = np.load(data_path)
        obs = data["obs"].astype(np.float64)
        actions = data["actions"].astype(np.float64)
        next_obs = data["next_obs"].astype(np.float64)
        delta_key = next_obs[:, :5] - obs[:, :5]
        scores = {}
        for i, name in enumerate(AGENT_NAMES):
            vals = [_safe_corr_abs(actions[:, i], delta_key[:, j]) for j in range(delta_key.shape[1])]
            scores[name] = float(np.mean(vals))
        max_v = max(scores.values()) + 1e-8
        # Blend data-derived sensitivity with a prior so values stay meaningful.
        out = {}
        for name in AGENT_NAMES:
            data_score = scores[name] / max_v
            out[name] = float(0.55 * data_score + 0.45 * fallback[name])
        return out
    except Exception:
        return fallback


def build_agent_features(data_path: str = "world_model_data/wm_transitions.npz") -> Tuple[np.ndarray, Dict[str, Dict[str, float]]]:
    """Build agent/task descriptors chi_i.

    Feature vector layout:
      0-4:  one-hot agent ID
      5:    local observation dimension ratio
      6:    prior task complexity
      7:    data-driven action sensitivity proxy
      8:    material coupling indicator
      9:    heat coupling indicator
      10:   storage coupling indicator
    """
    prior_complexity = {
        "Battery": 0.35,
        "P2A": 1.00,
        "CHP": 0.72,
        "GB": 0.55,
        "EB": 0.50,
    }
    material_coupling = {
        "Battery": 0.10,
        "P2A": 1.00,
        "CHP": 0.55,
        "GB": 0.45,
        "EB": 0.10,
    }
    heat_coupling = {
        "Battery": 0.10,
        "P2A": 0.20,
        "CHP": 0.90,
        "GB": 0.85,
        "EB": 0.80,
    }
    storage_coupling = {
        "Battery": 0.85,
        "P2A": 1.00,
        "CHP": 0.60,
        "GB": 0.50,
        "EB": 0.30,
    }
    sensitivity = compute_action_sensitivity_from_data(data_path)

    features = []
    details: Dict[str, Dict[str, float]] = {}
    max_obs_dim = max(len(AGENT_OBS_IDXS[n]) for n in AGENT_NAMES)
    for i, name in enumerate(AGENT_NAMES):
        one_hot = np.zeros(len(AGENT_NAMES), dtype=np.float32)
        one_hot[i] = 1.0
        f = np.concatenate([
            one_hot,
            np.array([
                len(AGENT_OBS_IDXS[name]) / max_obs_dim,
                prior_complexity[name],
                sensitivity[name],
                material_coupling[name],
                heat_coupling[name],
                storage_coupling[name],
            ], dtype=np.float32),
        ])
        features.append(f)
        details[name] = {
            "obs_ratio": float(f[5]),
            "prior_complexity": prior_complexity[name],
            "sensitivity": sensitivity[name],
            "material_coupling": material_coupling[name],
            "heat_coupling": heat_coupling[name],
            "storage_coupling": storage_coupling[name],
        }
    return np.asarray(features, dtype=np.float32), details


def build_target_initializers(features: np.ndarray) -> np.ndarray:
    """Create target initialization values for meta-training.

    The targets encode a reasonable prior: more complex agents receive slightly
    stronger PQC initialization scale, more input sensitivity, and agent-specific
    action-head bias. P2A receives a positive bias to avoid negative production at
    the beginning of training; EB is kept moderate to avoid saturation.
    """
    targets = []
    for i, f in enumerate(features):
        name = AGENT_NAMES[i]
        complexity = float(0.45 * f[6] + 0.35 * f[7] + 0.20 * max(f[8], f[9], f[10]))
        complexity = float(np.clip(complexity, 0.0, 1.0))
        theta_scale = 0.025 + 0.040 * complexity
        input_scale = 0.55 + 0.22 * complexity
        output_scale = 0.46 + 0.12 * complexity
        log_std = -1.08 + 0.18 * complexity
        ent_strength = 0.06 + 0.08 * complexity

        if name == "P2A":
            final_bias = 0.42
            output_scale = min(output_scale + 0.05, 0.68)
        elif name == "EB":
            final_bias = -0.10
            output_scale = min(output_scale, 0.55)
            log_std = -1.05
        elif name == "CHP":
            final_bias = 0.10
        elif name == "GB":
            final_bias = 0.18
        else:
            final_bias = 0.00

        targets.append([theta_scale, input_scale, output_scale, log_std, final_bias, ent_strength])
    return np.asarray(targets, dtype=np.float32)


def train_meta_initializer(
    features: np.ndarray,
    targets: np.ndarray,
    cfg: QMetaInitConfig | None = None,
    epochs: int = 2000,
    lr: float = 2e-3,
    device: torch.device | None = None,
):
    cfg = cfg or QMetaInitConfig(feature_dim=features.shape[1])
    device = device or torch.device("cuda" if torch.cuda.is_available() else "cpu")
    torch.manual_seed(cfg.seed)
    model = QMetaInitializer(cfg).to(device)
    opt = torch.optim.Adam(model.parameters(), lr=lr)
    x = torch.as_tensor(features, dtype=torch.float32, device=device)
    y = torch.as_tensor(targets, dtype=torch.float32, device=device)
    losses = []
    for _ in range(epochs):
        pred = model(x)
        loss = ((pred - y) ** 2).mean()
        opt.zero_grad(set_to_none=True)
        loss.backward()
        opt.step()
        losses.append(float(loss.detach().cpu()))
    return model, np.asarray(losses, dtype=np.float32)


def initializer_outputs_to_dict(outputs: np.ndarray) -> Dict[str, Dict[str, float]]:
    out: Dict[str, Dict[str, float]] = {}
    for i, name in enumerate(AGENT_NAMES):
        out[name] = {k: float(outputs[i, j]) for j, k in enumerate(INIT_KEYS)}
    return out


def save_meta_initializer(path: str, model: QMetaInitializer, cfg: QMetaInitConfig, features: np.ndarray, targets: np.ndarray, details: Dict):
    os.makedirs(os.path.dirname(path), exist_ok=True)
    payload = {
        "model": model.state_dict(),
        "cfg": asdict(cfg),
        "features": features,
        "targets": targets,
        "details": details,
        "agent_names": AGENT_NAMES,
        "init_keys": INIT_KEYS,
    }
    torch.save(payload, path)


def load_meta_initializer(path: str, device: torch.device):
    if not os.path.exists(path):
        raise FileNotFoundError(f"Q-MAML initializer not found: {path}. Run python train_qmaml_initializer.py first.")
    payload = torch.load(path, map_location=device, weights_only=False)
    cfg = QMetaInitConfig(**payload["cfg"])
    model = QMetaInitializer(cfg).to(device)
    model.load_state_dict(payload["model"])
    model.eval()
    return model, payload


def apply_qmaml_initialization(policy, initializer_path: str, device: torch.device, verbose: bool = True) -> Dict[str, Dict[str, float]]:
    """Apply Q-MAML-inspired initialization to an existing QMAPPO policy."""
    model, payload = load_meta_initializer(initializer_path, device)
    features = torch.as_tensor(payload["features"], dtype=torch.float32, device=device)
    with torch.no_grad():
        outputs = model(features).detach().cpu().numpy()

    init_dict = initializer_outputs_to_dict(outputs)

    with torch.no_grad():
        for name in AGENT_NAMES:
            actor = policy.actors[name]
            p = init_dict[name]
            theta_scale = p["theta_scale"]
            input_scale = p["input_scale"]
            output_scale = p["output_scale"]
            log_std = p["log_std"]
            final_bias = p["final_bias"]
            ent_strength = p["ent_strength"]

            actor.pqc.theta_rx.normal_(mean=0.0, std=theta_scale)
            actor.pqc.theta_ry.normal_(mean=0.0, std=theta_scale)
            actor.pqc.theta_rz.normal_(mean=0.0, std=theta_scale)
            actor.pqc.input_scale.fill_(input_scale)
            actor.pqc.ent_strength.fill_(ent_strength)
            actor.output_scale.fill_(output_scale)
            actor.log_std.fill_(log_std)
            actor.head[-1].bias.fill_(final_bias)
            # Keep final layer weights small so the learned bias and PQC features
            # determine a stable early policy instead of saturated actions.
            actor.head[-1].weight.mul_(0.35)

    if verbose:
        print("Applied Q-MAML-inspired initialization:")
        for name, vals in init_dict.items():
            compact = ", ".join([f"{k}={v:.3f}" for k, v in vals.items()])
            print(f"  {name}: {compact}")
    return init_dict
